/** Typed access to the JSON generated by scripts/build_data.py. */
import aiactJson from '../data/aiact.json';
import atlasJson from '../data/atlas.json';
import catalogueJson from '../data/catalogue.json';
import docsJson from '../data/catalogue-docs.json';
import type { EngineData } from './assess';
import type { AiActData, AtlasData, Catalogue, CatalogueDocs } from './types';

export const catalogue = catalogueJson as unknown as Catalogue;
export const aiact = aiactJson as unknown as AiActData;
export const atlas = atlasJson as unknown as AtlasData;
export const catalogueDocs = docsJson as unknown as CatalogueDocs;

export const engineData: EngineData = {
  catalogue,
  obligations: aiact.obligations,
  purposeVocabulary: aiact.purposeVocabulary.map((v) => v.id),
};

export const controlById = new Map(catalogue.controls.map((c) => [c.id, c]));
export const techniqueById = new Map(catalogue.techniques.map((t) => [t.id, t]));
export const flagById = new Map(catalogue.flags.map((f) => [f.id, f]));
export const phaseOrder = catalogue.meta.phases.map((p) => p.id);
